        self.time += 1

    def get_news_feed(self, user_id):
        followees = self.following.get(user_id, set()) | {user_id}
        all_tweets = []
        for f in followees:
            all_tweets.extend(self.tweets.get(f, []))        # gather EVERY tweet, no limit
        all_tweets.sort(key=lambda x: -x[0])
        return [tid for _, tid in all_tweets[:10]]

    def follow(self, follower_id, followee_id):
        self.following.setdefault(follower_id, set()).add(followee_id)

    def unfollow(self, follower_id, followee_id):
        self.following.get(follower_id, set()).discard(followee_id)

