import heapq

class Twitter:
    def __init__(self):
        self.time = 0
        self.tweets = {}                          # userId -> list of (time, tweetId)
        self.following = {}                       # userId -> set of followeeIds

    def post_tweet(self, user_id, tweet_id):
        self.tweets.setdefault(user_id, []).append((self.time, tweet_id))
        self.time += 1

    def get_news_feed(self, user_id):
        heap = []
        followees = self.following.get(user_id, set()) | {user_id}
        for f in followees:
            lst = self.tweets.get(f, [])
            if lst:
                idx = len(lst) - 1                       # start from each user's MOST RECENT tweet
                t, tid = lst[idx]
                heapq.heappush(heap, (-t, tid, f, idx - 1))
        result = []
        while heap and len(result) < 10:
            neg_t, tid, f, next_idx = heapq.heappop(heap)
            result.append(tid)
            if next_idx >= 0:
                t2, tid2 = self.tweets[f][next_idx]
                heapq.heappush(heap, (-t2, tid2, f, next_idx - 1))
        return result

    def follow(self, follower_id, followee_id):
        self.following.setdefault(follower_id, set()).add(followee_id)

    def unfollow(self, follower_id, followee_id):
        self.following.get(follower_id, set()).discard(followee_id)

