import java.util.*;

class Twitter {
    int time = 0;
    Map<Integer, List<int[]>> tweets = new HashMap<>();      // userId -> list of [time, tweetId]
    Map<Integer, Set<Integer>> following = new HashMap<>();

    void postTweet(int userId, int tweetId) {
        tweets.computeIfAbsent(userId, k -> new ArrayList<>()).add(new int[]{time++, tweetId});
    }

    List<Integer> getNewsFeed(int userId) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);  // max-heap by time
        Set<Integer> followees = new HashSet<>(following.getOrDefault(userId, new HashSet<>()));
        followees.add(userId);
        for (int f : followees) {
            List<int[]> lst = tweets.getOrDefault(f, new ArrayList<>());
            if (!lst.isEmpty()) {
                int idx = lst.size() - 1;                       // start from each user's MOST RECENT tweet
                heap.offer(new int[]{lst.get(idx)[0], lst.get(idx)[1], f, idx - 1});
            }
        }
        List<Integer> result = new ArrayList<>();
        while (!heap.isEmpty() && result.size() < 10) {
            int[] top = heap.poll();
            result.add(top[1]);
            if (top[3] >= 0) {
                int[] nextTweet = tweets.get(top[2]).get(top[3]);
                heap.offer(new int[]{nextTweet[0], nextTweet[1], top[2], top[3] - 1});
            }
        }
        return result;
    }

    void follow(int followerId, int followeeId) {
        following.computeIfAbsent(followerId, k -> new HashSet<>()).add(followeeId);
    }

    void unfollow(int followerId, int followeeId) {
        if (following.containsKey(followerId)) following.get(followerId).remove(followeeId);
    }
}

