#include <bits/stdc++.h>
using namespace std;

class Twitter {
public:
    int time_ = 0;
    unordered_map<int, vector<pair<int,int>>> tweets;         // userId -> list of (time, tweetId)
    unordered_map<int, unordered_set<int>> following;

    void postTweet(int userId, int tweetId) {
        tweets[userId].push_back({time_++, tweetId});
    }

    vector<int> getNewsFeed(int userId) {
        priority_queue<tuple<int,int,int,int>> heap;              // (time, tweetId, userId, nextIdx)
        unordered_set<int> followees = following[userId];
        followees.insert(userId);
        for (int f : followees) {
            auto& lst = tweets[f];
            if (!lst.empty()) {
                int idx = lst.size() - 1;                            // most recent tweet first
                heap.push({lst[idx].first, lst[idx].second, f, idx - 1});
            }
        }
        vector<int> result;
        while (!heap.empty() && (int)result.size() < 10) {
            auto [t, tid, f, nextIdx] = heap.top(); heap.pop();
            result.push_back(tid);
            if (nextIdx >= 0) {
                auto& nt = tweets[f][nextIdx];
                heap.push({nt.first, nt.second, f, nextIdx - 1});
            }
        }
        return result;
    }

    void follow(int followerId, int followeeId) { following[followerId].insert(followeeId); }
    void unfollow(int followerId, int followeeId) { following[followerId].erase(followeeId); }
};
